Theorem qhtr_0RB1LB_0RC1LA_1RD0LB_1LC1RC : NonHalt tm_0RB1LB_0RC1LA_1RD0LB_1LC1RC /\ QHBoundTr 32779478 tm_0RB1LB_0RC1LA_1RD0LB_1LC1RC /\ QuasiHaltsTr tm_0RB1LB_0RC1LA_1RD0LB_1LC1RC.
