  unfold Cin_0RB1LB_1LA0RC_0LD1RB_1RC1LD, cden, AI0_0RB1LB_1LA0RC_0LD1RB_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LB_1LA0RC_0LD1RB_1RC1LD) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB1LB_1LA0RC_0LD1RB_1RC1LD, cden, AI1_0RB1LB_1LA0RC_0LD1RB_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LB_1LA0RC_0LD1RB_1RC1LD).
  split; [lia|]. split; [| exact (gen_0RB1LB_1LA0RC_0LD1RB_1RC1LD v i q0 E)].
  rewrite (gsn_0RB1LB_1LA0RC_0LD1RB_1RC1LD v i q0 E).
  exact (srun_sound tm false true chn_0RB1LB_1LA0RC_0LD1RB_1RC1LD AI0_0RB1LB_1LA0RC_0LD1RB_1RC1LD AI1_0RB1LB_1LA0RC_0LD1RB_1RC1LD 4 8
           run_inner_0RB1LB_1LA0RC_0LD1RB_1RC1LD (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall j, lift (cden [] [] j BB1_0RB1LB_1LA0RC_0LD1RB_1RC1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LB_1LA0RC_0LD1RB_1RC1LD = (StD, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_0RB1LB_1LA0RC_0LD1RB_1RC1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB1LB_1LA0RC_0LD1RB_1RC1LD. rewrite epow2_0RB1LB_1LA0RC_0LD1RB_1RC1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LB_1LA0RC_0LD1RB_1RC1LD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1LB_1LA0RC_0LD1RB_1RC1LD.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LB_1LA0RC_0LD1RB_1RC1LD, cden, BE0_0RB1LB_1LA0RC_0LD1RB_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB1LB_1LA0RC_0LD1RB_1RC1LD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LB_1LA0RC_0LD1RB_1RC1LD p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB1LB_1LA0RC_0LD1RB_1RC1LD).
    split; [lia|]. split; [| exact (gbo_0RB1LB_1LA0RC_0LD1RB_1RC1LD j)].
    rewrite (gso_0RB1LB_1LA0RC_0LD1RB_1RC1LD p j E).
    exact (srun_sound tm true true chb_0RB1LB_1LA0RC_0LD1RB_1RC1LD B0_0RB1LB_1LA0RC_0LD1RB_1RC1LD BB1_0RB1LB_1LA0RC_0LD1RB_1RC1LD 4 8
             run_boot_0RB1LB_1LA0RC_0LD1RB_1RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 19), (cden [] [] j B1_0RB1LB_1LA0RC_0LD1RB_1RC1LD).
    split; [| exact (geo_0RB1LB_1LA0RC_0LD1RB_1RC1LD p j E)].
    rewrite (gxi_0RB1LB_1LA0RC_0LD1RB_1RC1LD j).
    exact (srun_sound tm true true che_0RB1LB_1LA0RC_0LD1RB_1RC1LD BE0_0RB1LB_1LA0RC_0LD1RB_1RC1LD B1_0RB1LB_1LA0RC_0LD1RB_1RC1LD 8 19
             run_exit_0RB1LB_1LA0RC_0LD1RB_1RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_0RB1LB_1LA0RC_0LD1RB_1RC1LD = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_0RB1LB_1LA0RC_0LD1RB_1RC1LD q p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB1LB_1LA0RC_0LD1RB_1RC1LD). split;
      [| exact (gbo_0RB1LB_1LA0RC_0LD1RB_1RC1LD j)].
    rewrite (gso_0RB1LB_1LA0RC_0LD1RB_1RC1LD p j E).
    exact (srun_sound tm true true chb_0RB1LB_1LA0RC_0LD1RB_1RC1LD B0_0RB1LB_1LA0RC_0LD1RB_1RC1LD BB1_0RB1LB_1LA0RC_0LD1RB_1RC1LD 4 8
             run_boot_0RB1LB_1LA0RC_0LD1RB_1RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LB_1LA0RC_0LD1RB_1RC1LD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1LB_1LA0RC_0LD1RB_1RC1LD j)].
Qed.



(** ** The lap *)

Lemma lap_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LB_1LA0RC_0LD1RB_1RC1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LB_1LA0RC_0LD1RB_1RC1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB1LB_1LA0RC_0LD1RB_1RC1LD : stepn tm_0RB1LB_1LA0RC_0LD1RB_1RC1LD 16 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tm_0RB1LB_1LA0RC_0LD1RB_1RC1LD 16 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm_0RB1LB_1LA0RC_0LD1RB_1RC1LD 16 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB1LB_1LA0RC_0LD1RB_1RC1LD : existsb (fun tg => cfires tm_0RB1LB_1LA0RC_0LD1RB_1RC1LD c0 16 tg) pins_0RB1LB_1LA0RC_0LD1RB_1RC1LD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LB_1LA0RC_0LD1RB_1RC1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LB_1LA0RC_0LD1RB_1RC1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LB_1LA0RC_0LD1RB_1RC1LD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LB_1LA0RC_0LD1RB_1RC1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1LB_1LA0RC_0LD1RB_1RC1LD t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB1LB_1LA0RC_0LD1RB_1RC1LD). split;
      [| exact (gbo_0RB1LB_1LA0RC_0LD1RB_1RC1LD j)].
    rewrite (gso_0RB1LB_1LA0RC_0LD1RB_1RC1LD p j E).
    exact (srun_sound tm true true chb_0RB1LB_1LA0RC_0LD1RB_1RC1LD B0_0RB1LB_1LA0RC_0LD1RB_1RC1LD BB1_0RB1LB_1LA0RC_0LD1RB_1RC1LD 4 8
             run_boot_0RB1LB_1LA0RC_0LD1RB_1RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LB_1LA0RC_0LD1RB_1RC1LD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1LB_1LA0RC_0LD1RB_1RC1LD j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LB_1LA0RC_0LD1RB_1RC1LD : forall t, ~ In t pins_0RB1LB_1LA0RC_0LD1RB_1RC1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB1LB_1LA0RC_0LD1RB_1RC1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
