Definition tm_0RB1LB_1RC1LB_0LB1RD_0LA0RC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StB
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LB_1RC1LB_0LB1RD_0LA0RC : list Instr := [(StA, S0)].
Definition tmw_0RB1LB_1RC1LB_0LB1RD_0LA0RC : TM := tm_wrap_trs tm_0RB1LB_1RC1LB_0LB1RD_0LA0RC pins_0RB1LB_1RC1LB_0LB1RD_0LA0RC.
Local Notation tm := tmw_0RB1LB_1RC1LB_0LB1RD_0LA0RC.

Definition Cc_0RB1LB_1RC1LB_0LB1RD_0LA0RC (p : positive) : cconf := (StD, (Ap_Alph_10_11_11 p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB1LB_1RC1LB_0LB1RD_0LA0RC.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StD (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_0RB1LB_1RC1LB_0LB1RD_0LA0RC : list lstep := [SWin 4].

Lemma run_z_0RB1LB_1RC1LB_0LB1RD_0LA0RC : srun tm false true chz_0RB1LB_1RC1LB_0LB1RD_0LA0RC Z0_0RB1LB_1RC1LB_0LB1RD_0LA0RC = Some (Z1_0RB1LB_1RC1LB_0LB1RD_0LA0RC, 0, 4).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition P1_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StD (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_0RB1LB_1RC1LB_0LB1RD_0LA0RC : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_p_0RB1LB_1RC1LB_0LB1RD_0LA0RC : srun tm false true chp_0RB1LB_1RC1LB_0LB1RD_0LA0RC P0_0RB1LB_1RC1LB_0LB1RD_0LA0RC = Some (P1_0RB1LB_1RC1LB_0LB1RD_0LA0RC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StD (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StB *)
Definition Cin_0RB1LB_1RC1LB_0LB1RD_0LA0RC (v : positive) : cconf := (StB, (Ip v ++ [S1], S0, [])).
Local Notation Cin := Cin_0RB1LB_1RC1LB_0LB1RD_0LA0RC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1LB_1RC1LB_0LB1RD_0LA0RC : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chn_0RB1LB_1RC1LB_0LB1RD_0LA0RC : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_0RB1LB_1RC1LB_0LB1RD_0LA0RC : srun tm false true chn_0RB1LB_1RC1LB_0LB1RD_0LA0RC AI0_0RB1LB_1RC1LB_0LB1RD_0LA0RC = Some (AI1_0RB1LB_1RC1LB_0LB1RD_0LA0RC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chb_0RB1LB_1RC1LB_0LB1RD_0LA0RC : list lstep := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 3; SUnrotL 1].

Lemma run_boot_0RB1LB_1RC1LB_0LB1RD_0LA0RC : srun tm true true chb_0RB1LB_1RC1LB_0LB1RD_0LA0RC B0_0RB1LB_1RC1LB_0LB1RD_0LA0RC = Some (BB1_0RB1LB_1RC1LB_0LB1RD_0LA0RC, 4, 7).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LB_1RC1LB_0LB1RD_0LA0RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1LB_1RC1LB_0LB1RD_0LA0RC : list lstep := [SWinR 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_0RB1LB_1RC1LB_0LB1RD_0LA0RC : srun tm true true che_0RB1LB_1RC1LB_0LB1RD_0LA0RC BE0_0RB1LB_1RC1LB_0LB1RD_0LA0RC = Some (B1_0RB1LB_1RC1LB_0LB1RD_0LA0RC, 4, 9).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1LB_1RC1LB_0LB1RD_0LA0RC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_0RB1LB_1RC1LB_0LB1RD_0LA0RC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_0RB1LB_1RC1LB_0LB1RD_0LA0RC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1LB_1RC1LB_0LB1RD_0LA0RC, cden, Z0_0RB1LB_1RC1LB_0LB1RD_0LA0RC, Z1_0RB1LB_1RC1LB_0LB1RD_0LA0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1LB_1RC1LB_0LB1RD_0LA0RC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_0RB1LB_1RC1LB_0LB1RD_0LA0RC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_0RB1LB_1RC1LB_0LB1RD_0LA0RC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1LB_1RC1LB_0LB1RD_0LA0RC, cden, P0_0RB1LB_1RC1LB_0LB1RD_0LA0RC, P1_0RB1LB_1RC1LB_0LB1RD_0LA0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LB_1RC1LB_0LB1RD_0LA0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1LB_1RC1LB_0LB1RD_0LA0RC p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB1LB_1RC1LB_0LB1RD_0LA0RC Z0_0RB1LB_1RC1LB_0LB1RD_0LA0RC Z1_0RB1LB_1RC1LB_0LB1RD_0LA0RC 0 4
               run_z_0RB1LB_1RC1LB_0LB1RD_0LA0RC (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB1LB_1RC1LB_0LB1RD_0LA0RC p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB1LB_1RC1LB_0LB1RD_0LA0RC P0_0RB1LB_1RC1LB_0LB1RD_0LA0RC P1_0RB1LB_1RC1LB_0LB1RD_0LA0RC 4 8
               run_p_0RB1LB_1RC1LB_0LB1RD_0LA0RC (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB1LB_1RC1LB_0LB1RD_0LA0RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LB_1RC1LB_0LB1RD_0LA0RC.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_0RB1LB_1RC1LB_0LB1RD_0LA0RC, cden, B0_0RB1LB_1RC1LB_0LB1RD_0LA0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LB_1RC1LB_0LB1RD_0LA0RC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LB_1RC1LB_0LB1RD_0LA0RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LB_1RC1LB_0LB1RD_0LA0RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LB_1RC1LB_0LB1RD_0LA0RC
             = (StD, (rep [S1;S0] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_0RB1LB_1RC1LB_0LB1RD_0LA0RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LB_1RC1LB_0LB1RD_0LA0RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1LB_1RC1LB_0LB1RD_0LA0RC. reflexivity.
Qed.

Lemma gsn_0RB1LB_1RC1LB_0LB1RD_0LA0RC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_0RB1LB_1RC1LB_0LB1RD_0LA0RC.
Proof.
