(** ** The lap *)

Lemma lap_0RB1LB_1RC1LB_1LA1RD_0LB0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
