  - destruct (lapi_0RB1LB_1RC1LB_1LA1RD_0LB0RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LB_1RC1LB_1LA1RD_0LB0RC B0_0RB1LB_1RC1LB_1LA1RD_0LB0RC B1_0RB1LB_1RC1LB_1LA1RD_0LB0RC 4 15 p j' [] []).
    + exact run_ovf_0RB1LB_1RC1LB_1LA1RD_0LB0RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LB_1RC1LB_1LA1RD_0LB0RC p j' E).
    + exact (geo_0RB1LB_1RC1LB_1LA1RD_0LB0RC p j' E).
    + lia.
Qed.

