    apply (fire_via_int_lift tm Cc lap_0RB1LC_1LA1RB_0LD0LA_1RA1RA (StC, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_0RB1LC_1LA1RB_0LD0LA_1RA1RA [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1LC_1LA1RB_0LD0LA_1RA1RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* D0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D1: fires only in the interior lap *)
