    apply (fire_via_int_lift tm Cc lap_0RB1LC_1LA1RB_0LD0LA_1RA1RA (StD, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_0RB1LC_1LA1RB_0LD0LA_1RA1RA [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
Qed.

