Definition mk_0RB1LC_1LA1RB_0LD0LA_1RD1RA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1LC_1LA1RB_0LD0LA_1RD1RA.

(** 0RB1LC_1LA1RB_0LD0LA_1RD1RA *)
(** 0RB1LC_1LA1RB_0LD0LA_1RD1RA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LC_1LA1RB_0LD0LA_1RD1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S0 DL StA
  | StD, S0 => mk S1 DR StD | StD, S1 => mk S1 DR StA end.

(** Its mirror 0LB1RC_1RA1LB_0RD0RA_1LD1LA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LC_1LA1RB_0LD0LA_1RD1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S0 DR StA
  | StD, S0 => mk S1 DL StD | StD, S1 => mk S1 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LC_1LA1RB_0LD0LA_1RD1RA : list Instr := [(StD, S0)].
Definition tmw_0RB1LC_1LA1RB_0LD0LA_1RD1RA : TM := tm_wrap_trs tmm_0RB1LC_1LA1RB_0LD0LA_1RD1RA pins_0RB1LC_1LA1RB_0LD0LA_1RD1RA.
Local Notation tm := tmw_0RB1LC_1LA1RB_0LD0LA_1RD1RA.

Lemma mirror_ok_0RB1LC_1LA1RB_0LD0LA_1RD1RA : mirror_tm tm_0RB1LC_1LA1RB_0LD0LA_1RD1RA = tmm_0RB1LC_1LA1RB_0LD0LA_1RD1RA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

