Lemma gen_0RB1LC_1LA1RB_0LD0LA_1RD1RA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LC_1LA1RB_0LD0LA_1RD1RA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB1LC_1LA1RB_0LD0LA_1RD1RA, cden, AI1_0RB1LC_1LA1RB_0LD0LA_1RD1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1LC_1LA1RB_0LD0LA_1RD1RA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LC_1LA1RB_0LD0LA_1RD1RA).
  split; [lia|]. split; [| exact (gen_0RB1LC_1LA1RB_0LD0LA_1RD1RA v i q0 E)].
  rewrite (gsn_0RB1LC_1LA1RB_0LD0LA_1RD1RA v i q0 E).
  exact (srun_sound tm false true chn_0RB1LC_1LA1RB_0LD0LA_1RD1RA AI0_0RB1LC_1LA1RB_0LD0LA_1RD1RA AI1_0RB1LC_1LA1RB_0LD0LA_1RD1RA 4 8
           run_inner_0RB1LC_1LA1RB_0LD0LA_1RD1RA (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB1LC_1LA1RB_0LD0LA_1RD1RA : forall j, lift (cden [] [] j BB1_0RB1LC_1LA1RB_0LD0LA_1RD1RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LC_1LA1RB_0LD0LA_1RD1RA = (StB, (rep [S1;S0] j ++ [S1;S1], S0, [S0;S1;S1;S1]))).
  { unfold cden, BB1_0RB1LC_1LA1RB_0LD0LA_1RD1RA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, [S0;S1;S1;S1]))).
  { unfold Cin_0RB1LC_1LA1RB_0LD0LA_1RD1RA. rewrite epow2_0RB1LC_1LA1RB_0LD0LA_1RD1RA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LC_1LA1RB_0LD0LA_1RD1RA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LC_1LA1RB_0LD0LA_1RD1RA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1LC_1LA1RB_0LD0LA_1RD1RA.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LC_1LA1RB_0LD0LA_1RD1RA, cden, BE0_0RB1LC_1LA1RB_0LD0LA_1RD1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LC_1LA1RB_0LD0LA_1RD1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1LC_1LA1RB_0LD0LA_1RD1RA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LC_1LA1RB_0LD0LA_1RD1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LC_1LA1RB_0LD0LA_1RD1RA p (pow2 j)).
  - exists (4 * j + 7), (cden [] [] j BB1_0RB1LC_1LA1RB_0LD0LA_1RD1RA).
    split; [lia|]. split; [| exact (gbo_0RB1LC_1LA1RB_0LD0LA_1RD1RA j)].
    rewrite (gso_0RB1LC_1LA1RB_0LD0LA_1RD1RA p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LA1RB_0LD0LA_1RD1RA B0_0RB1LC_1LA1RB_0LD0LA_1RD1RA BB1_0RB1LC_1LA1RB_0LD0LA_1RD1RA 4 7
             run_boot_0RB1LC_1LA1RB_0LD0LA_1RD1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 11), (cden [] [] j B1_0RB1LC_1LA1RB_0LD0LA_1RD1RA).
    split; [| exact (geo_0RB1LC_1LA1RB_0LD0LA_1RD1RA p j E)].
    rewrite (gxi_0RB1LC_1LA1RB_0LD0LA_1RD1RA j).
    exact (srun_sound tm true true che_0RB1LC_1LA1RB_0LD0LA_1RD1RA BE0_0RB1LC_1LA1RB_0LD0LA_1RD1RA B1_0RB1LC_1LA1RB_0LD0LA_1RD1RA 4 11
             run_exit_0RB1LC_1LA1RB_0LD0LA_1RD1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1LC_1LA1RB_0LD0LA_1RD1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LC_1LA1RB_0LD0LA_1RD1RA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LC_1LA1RB_0LD0LA_1RD1RA p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB1LC_1LA1RB_0LD0LA_1RD1RA : stepn tmm_0RB1LC_1LA1RB_0LD0LA_1RD1RA 60 InitES = Some (lift (Cc 2)).
Proof.
  assert (H : match csteps tmm_0RB1LC_1LA1RB_0LD0LA_1RD1RA 60 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_0RB1LC_1LA1RB_0LD0LA_1RD1RA 60 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
