    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB1LC_1LC1RB_0RB1LD_0RA0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1LC_1LC1RB_0RB1LD_0RA0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
