  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1LC_1RC0LD_0RD0LA_1LA1RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1LC_1RC0LD_0RD0LA_1LA1RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
